function [v] = kpi_ticks_ran_percent(ran, ticks)
%KPI_TICKS_RAN_PERCENT  The share [%] of a rate group's ticks on which it ran: ran of ticks (nan with no tick). The loop counts the ticks of the
%   fine-pointing states with an attitude and those on which the control law ran, seen as its torque request changing
%   (held between its runs).
%   ran: int (passed a whole number)
%   ticks: int (passed a whole number)
%   returns v: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    v = 0;
    v = NaN;
    if (ticks > 0)
        v = ((100 * ran) / ticks);
    end
end
